Inductive wt : Type :=
| WLit (z : Z) | WVar (v : pv)
| WAlu (op : aluop) (a b : wt) | WAluw (op : aluop) (a b : wt)
| WMd (op : mulop) (a b : wt) | WMdw (op : mulop) (a b : wt)
| WExt (sx : bool) (lo n : nat) (a : wt).
Fixpoint winst (p : me_params) (t : wt) : word :=
  match t with
  | WLit z => Z_to_bv 64 z
  | WVar v => pget p v
  | WAlu op a b => alu64 op (winst p a) (winst p b)
  | WAluw op a b => sext 64 (alu32 op (low32 (winst p a)) (low32 (winst p b)))
  | WMd op a b => mul_div op (winst p a) (winst p b)
  | WMdw op a b => sext 64 (mul_div op (low32 (winst p a)) (low32 (winst p b)))
  | WExt sx lo n a => ext_val sx lo n (winst p a)
  end.
(* [comment removed for export] *)
Inductive at_ : Type := ALit (z : Z) | AOff (base : wt) (off : Z).
Definition ainst (p : me_params) (a : at_) : word :=
  match a with ALit z => Z_to_bv 64 z | AOff b off => v_addi (winst p b) off end.
(* [comment removed for export] *)
Definition azinst (p : me_params) (a : at_) : Z :=
  match a with ALit z => z | AOff b off => bv_unsigned (winst p b) + off end.
(* [comment removed for export] *)
Inductive ct : Type :=
| TWord (a : at_) (w : nat) (v : wt) | TZero (a : at_) (n : wt) | TFill (a : at_) (n : wt) (c : Z)
| TUnk (a : at_) (n : wt) | TWr (a : at_) (n : wt) | TImg (lo hi : Z).
Definition cinst (p : me_params) (c : ct) : cell :=
  match c with
  | TWord a w v => CWord (ainst p a) w (winst p v)
  | TZero a n => CZero (ainst p a) (winst p n)
  | TFill a n c => CFill (ainst p a) (winst p n) c
  | TUnk a n => CUnk (ainst p a) (winst p n)
  | TWr a n => CWr (ainst p a) (winst p n)
  | TImg lo hi => CImg lo hi
  end.
(* [comment removed for export] *)
Inductive nt : Type := NRange (lo : Z) (v : wt) (hi : Z) | NDisj (a : at_) (n : wt) (b : at_) (m : wt) | NAlign (v : wt) (m : Z).
Definition ninst (p : me_params) (c : nt) : cnst :=
  match c with
  | NRange lo v hi => CRange lo (winst p v) hi
  | NDisj a n b m => CDisj (azinst p a) (bv_unsigned (winst p n)) (azinst p b) (bv_unsigned (winst p m))
  | NAlign v m => CAlignm (winst p v) m
  end.

Coercion WVar : pv >-> wt.
Declare Scope tm_scope. Delimit Scope tm_scope with tm.
Notation "# z" := (WLit z) (at level 1, format "# z") : tm_scope.
Notation "a + b" := (WAlu Instr.ALU_ADD a b) : tm_scope.
Notation "a * b" := (WMd Instr.M_MUL a b) : tm_scope.
Notation "a & b" := (WAlu Instr.ALU_AND a b) (at level 40, left associativity) : tm_scope.
Notation "a <u b" := (WAlu Instr.ALU_SLTU a b) (at level 45, no associativity) : tm_scope.
Notation "@ z" := (ALit z) (at level 1, format "@ z") : tm_scope.
Notation "b .+ off" := (AOff b off) (at level 50, left associativity) : tm_scope.
